import sqlite3
import uuid
import json
import asyncio
import io
import os
from typing import List, Optional, Tuple
from contextlib import asynccontextmanager

from fastapi import FastAPI, File, Form, UploadFile, HTTPException
from fastapi.responses import Response

# Privacy: strip invisible metadata from uploaded files
try:
    from PIL import Image
except ImportError:
    Image = None

try:
    import PyPDF2
except ImportError:
    PyPDF2 = None


def strip_image_metadata(content: bytes) -> bytes:
    """Remove all metadata from an image by re-encoding pixel data only."""
    if Image is None:
        raise RuntimeError("Pillow is not installed")
    img = Image.open(io.BytesIO(content))
    # Create a new image with the same mode and size, copy pixel data
    new_img = Image.new(img.mode, img.size)
    new_img.putdata(list(img.getdata()))
    output = io.BytesIO()
    new_img.save(output, format=img.format)
    return output.getvalue()


def strip_pdf_metadata(content: bytes) -> bytes:
    """Remove metadata (Info and XMP) from a PDF."""
    if PyPDF2 is None:
        raise RuntimeError("PyPDF2 is not installed")
    reader = PyPDF2.PdfReader(io.BytesIO(content))
    writer = PyPDF2.PdfWriter()
    for page in reader.pages:
        writer.add_page(page)
    # Clear standard Info dictionary
    writer.add_metadata({})
    # Remove XMP metadata stream if present
    if hasattr(writer, '_root_object') and '/Metadata' in writer._root_object:
        del writer._root_object['/Metadata']
    output = io.BytesIO()
    writer.write(output)
    return output.getvalue()


def strip_invisible_metadata(content: bytes, filename: str) -> bytes:
    """Strip invisible metadata based on file extension."""
    ext = os.path.splitext(filename)[1].lower()
    if ext in ('.jpg', '.jpeg', '.png', '.tiff', '.bmp', '.gif'):
        return strip_image_metadata(content)
    elif ext == '.pdf':
        return strip_pdf_metadata(content)
    else:
        # For unsupported types, we cannot guarantee stripping; return as-is.
        # In a production system you would either reject or use a more comprehensive tool.
        return content


@asynccontextmanager
async def lifespan(app: FastAPI):
    with sqlite3.connect("db.sqlite3") as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS files (
                file_id TEXT PRIMARY KEY,
                owner_id TEXT,
                allowed_viewers TEXT,
                file_content BLOB
            )
            """
        )
        conn.commit()
        yield


app = FastAPI(lifespan=lifespan)


def _save_file(file_id: str, owner_id: str, allowed_viewers: List[str], content: bytes) -> None:
    with sqlite3.connect("db.sqlite3") as conn:
        conn.execute(
            "INSERT INTO files (file_id, owner_id, allowed_viewers, file_content) VALUES (?, ?, ?, ?)",
            (file_id, owner_id, json.dumps(allowed_viewers), content),
        )
        conn.commit()


def _get_file(file_id: str) -> Optional[Tuple[bytes, str, str]]:
    with sqlite3.connect("db.sqlite3") as conn:
        cursor = conn.execute(
            "SELECT file_content, owner_id, allowed_viewers FROM files WHERE file_id = ?",
            (file_id,),
        )
        row = cursor.fetchone()
    return row


@app.post("/files", status_code=201)
async def upload_file(
    file: UploadFile = File(...),
    owner_id: str = Form(...),
    allowed_viewers: List[str] = Form(default=[]),
):
    file_content = await file.read()
    try:
        sanitized_content = await asyncio.to_thread(
            strip_invisible_metadata, file_content, file.filename
        )
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to process file: {str(e)}")
    file_id = str(uuid.uuid4())
    await asyncio.to_thread(_save_file, file_id, owner_id, allowed_viewers, sanitized_content)
    return {"file_id": file_id}


@app.get("/files/{fileId}")
async def download_file(fileId: str, requester_id: str):
    row = await asyncio.to_thread(_get_file, fileId)
    if row is None:
        raise HTTPException(status_code=404, detail="File not found")
    content, owner_id, allowed_viewers_json = row
    allowed_viewers = json.loads(allowed_viewers_json)
    if requester_id != owner_id and requester_id not in allowed_viewers:
        raise HTTPException(status_code=403, detail="Access denied")
    return Response(content=content, media_type="application/octet-stream")


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
